select private.upsert_row('public','content_sections','{"id":"journey","kind":"journey","enabled":true,"position":6,"title":{"en":"Made for your moment","ar":"تُجهّز للحظتك","he":"מוכן לרגע שלך"},"body":{"en":"Choose your piece and its details. We prepare your order and keep you informed as it makes its way to you.","ar":"اختر قطعتك وتفاصيلها. نجهّز طلبك ونطلعك على مستجداته حتى يصل إليك.","he":"בחרו תכשיט ואת פרטיו. נכין את ההזמנה ונעדכן אתכם בדרכה אליכם."},"cta":{"en":"Discover THURAYA","ar":"اكتشف ثُرَيّا","he":"לגלות את THURAYA"},"href":"/shop","image":"/media/04-Vega-2colors-1-.jpeg","selection":[],"layout":"split"}'::jsonb);
select private.upsert_row('public','content_sections','{"id":"story","kind":"story","enabled":true,"position":7,"title":{"en":"A name written in the stars","ar":"اسمٌ كُتب بين النجوم","he":"שם שנכתב בכוכבים"},"body":{"en":"THURAYA takes its name from ثُرَيّا, the Pleiades. A small gathering of light, remembered across generations. Our jewelry carries that quiet sense of wonder into the everyday.","ar":"تستمد ثُرَيّا اسمها من عنقود النجوم المعروف. اجتماع صغير من النور، تتناقله ذاكرة الأجيال. تحمل مجوهراتنا ذلك الإحساس الهادئ بالدهشة إلى تفاصيل كل يوم.","he":"THURAYA נקראת על שם ثُرَيّا, צביר הכוכבים כימה. מקבץ קטן של אור, הזכור מדור לדור. התכשיטים שלנו מביאים את תחושת הפליאה השקטה הזאת אל היומיום."},"cta":{"en":"Discover THURAYA","ar":"اكتشف ثُرَيّا","he":"לגלות את THURAYA"},"href":"/about","image":"/media/04-Vega-2colors-1-.jpeg","selection":[],"layout":"split"}'::jsonb);
select private.upsert_row('public','content_sections','{"id":"packaging","kind":"packaging","enabled":true,"position":8,"title":{"en":"The final detail","ar":"التفصيل الأخير","he":"הפרט האחרון"},"body":{"en":"A considered presentation, in THURAYA’s midnight palette. See each piece for its confirmed packaging details.","ar":"تقديم مدروس بألوان ثُرَيّا الليلية. راجع تفاصيل كل قطعة لمعرفة التغليف المشمول.","he":"הגשה מוקפדת בגווני הלילה של THURAYA. פרטי האריזה המאושרים מופיעים בכל תכשיט."},"cta":{"en":"Discover THURAYA","ar":"اكتشف ثُرَيّا","he":"לגלות את THURAYA"},"href":"/shop","image":"/media/04-Vega-2colors-1-.jpeg","selection":[],"layout":"split"}'::jsonb);
select private.upsert_row('public','content_pages','{"id":"moissanite","slug":"moissanite","title":{"en":"What is moissanite?","ar":"ما هو المويسانيت؟","he":"מהו מויסנייט?"},"body":{"en":"Moissanite is a gemstone made of silicon carbide. It is a different material from diamond. Choosing between stones begins with understanding what each one is. Read the specifications of your chosen piece: stone type, dimensions and any grading or certification are shown only when confirmed for that product.","ar":"المويسانيت حجر يتكوّن من كربيد السيليكون، وهو مادة مختلفة عن الألماس. يبدأ اختيار الحجر بفهم طبيعته. راجع مواصفات القطعة التي تختارها: نوع الحجر وأبعاده ودرجاته أو شهادته لا تُعرض إلا عند تأكيدها لهذا المنتج.","he":"מויסנייט הוא אבן העשויה מסיליקון קרביד. זהו חומר שונה מיהלום. הבחירה בין אבנים מתחילה בהבנת ההבדלים ביניהן. עיינו במפרט התכשיט שבחרתם: סוג האבן, מידותיה ודירוג או תעודה מוצגים רק כאשר אושרו עבור אותו מוצר."},"kind":"education","status":"published","legal_reviewed":false}'::jsonb);
select private.upsert_row('public','content_pages','{"id":"lab-grown-diamonds","slug":"lab-grown-diamonds","title":{"en":"Lab-grown diamonds","ar":"الألماس المزروع في المختبر","he":"יהלומים שגודלו במעבדה"},"body":{"en":"Lab-grown diamonds are diamonds produced in a laboratory. They are distinct from diamond simulants such as moissanite. THURAYA is designed to welcome future lab-grown diamond collections. Availability and specifications are always stated on the individual product page.","ar":"الألماس المزروع في المختبر هو ألماس يُنتج في بيئة مختبرية، ويختلف عن الأحجار المشابهة للألماس مثل المويسانيت. يتيح متجر ثُرَيّا إضافة مجموعات من الألماس المزروع مستقبلًا. يُذكر التوفّر والمواصفات دائمًا في صفحة المنتج المعني.","he":"יהלומים שגודלו במעבדה הם יהלומים המיוצרים במעבדה. הם שונים מחיקויי יהלום כגון מויסנייט. החנות של THURAYA ערוכה לקולקציות עתידיות של יהלומי מעבדה. זמינות ומפרט יצוינו תמיד בעמוד המוצר המסוים."},"kind":"education","status":"published","legal_reviewed":false}'::jsonb);
select private.upsert_row('public','content_pages','{"id":"jewelry-care","slug":"jewelry-care","title":{"en":"Caring for your piece","ar":"العناية بقطعتك","he":"טיפול בתכשיט"},"body":{"en":"Care depends on the stone, metal, plating and setting. Follow the care information provided with your piece. Store jewelry separately to limit rubbing, and ask THURAYA before using chemical cleaners or ultrasonic equipment on an unfamiliar setting.","ar":"تختلف العناية بحسب الحجر والمعدن والطلاء والتثبيت. اتبع تعليمات العناية المرفقة بقطعتك. احفظ المجوهرات منفصلة لتقليل الاحتكاك، واستشر ثُرَيّا قبل استخدام المنظفات الكيميائية أو أجهزة التنظيف بالموجات فوق الصوتية على تثبيت غير مألوف.","he":"הטיפול תלוי באבן, במתכת, בציפוי ובשיבוץ. פעלו לפי הוראות הטיפול של התכשיט. אחסנו תכשיטים בנפרד כדי להפחית חיכוך, ופנו ל-THURAYA לפני שימוש בחומרי ניקוי כימיים או בציוד אולטרסוני לשיבוץ שאינכם מכירים."},"kind":"education","status":"published","legal_reviewed":false}'::jsonb);
select private.upsert_row('public','content_pages','{"id":"ring-size","slug":"ring-size","title":{"en":"Finding your ring size","ar":"اختيار مقاس الخاتم","he":"בחירת מידת טבעת"},"body":{"en":"A comfortable ring fits securely while passing over the knuckle. Fit can change during the day. Compare with a ring that fits the same finger, and contact our concierge to confirm the size system used by your chosen piece. Screen and paper measurements are estimates; do not assume a universal conversion.","ar":"يستقر الخاتم المريح بأمان مع إمكانية مروره فوق مفصل الإصبع. قد يتغيّر المقاس خلال اليوم. قارن بخاتم مناسب للإصبع نفسه وتواصل معنا لتأكيد نظام المقاسات الخاص بالقطعة. قياسات الشاشة والورق تقديرية؛ لا تفترض وجود تحويل موحّد.","he":"טבעת נוחה יושבת בבטחה ועוברת מעל מפרק האצבע. ההתאמה עשויה להשתנות במהלך היום. השוו לטבעת המתאימה לאותה אצבע ופנו אלינו לאישור שיטת המידות של התכשיט. מדידות מסך ונייר הן הערכה בלבד; אין להניח שהמרה אחת מתאימה לכל שיטה."},"kind":"education","status":"published","legal_reviewed":false}'::jsonb);
select private.upsert_row('public','content_pages','{"id":"necklace-length","slug":"necklace-length","title":{"en":"Choosing a necklace length","ar":"اختيار طول القلادة","he":"בחירת אורך שרשרת"},"body":{"en":"Use a soft measuring tape or a cord to explore where you would like a necklace to sit. The same length rests differently on different people. Select a configured length on the product page, or request a custom length when available. A custom inquiry is confirmed and priced separately.","ar":"استخدم شريط قياس مرنًا أو خيطًا لتحديد موضع القلادة المرغوب. يظهر الطول نفسه بشكل مختلف من شخص لآخر. اختر طولًا متاحًا في صفحة المنتج أو اطلب طولًا خاصًا عند إتاحة ذلك. يُؤكّد الطلب الخاص ويُسعّر بصورة منفصلة.","he":"השתמשו בסרט מדידה רך או בחוט כדי לבדוק היכן תרצו שהשרשרת תנוח. אותו אורך יושב אחרת על אנשים שונים. בחרו אורך זמין בעמוד המוצר, או בקשו אורך מותאם אם האפשרות קיימת. בקשה מותאמת דורשת אישור ותמחור נפרדים."},"kind":"education","status":"published","legal_reviewed":false}'::jsonb);
select private.upsert_row('public','content_pages','{"id":"bracelet-size","slug":"bracelet-size","title":{"en":"Choosing a bracelet fit","ar":"اختيار مقاس السوار","he":"בחירת מידת צמיד"},"body":{"en":"Measure the wrist gently with a flexible tape and consider whether you prefer a closer or looser fit. Clasp and design affect comfort. Confirm the available lengths on the product page; our concierge can help with a custom-length request when the piece allows it.","ar":"قِس المعصم برفق بشريط مرن وحدّد ما إذا كنت تفضّل السوار قريبًا أو أوسع. يؤثر القفل والتصميم في الراحة. راجع الأطوال المتاحة في صفحة المنتج؛ يمكن لفريقنا مساعدتك بطلب طول خاص عندما تسمح القطعة بذلك.","he":"מדדו את פרק כף היד בעדינות בסרט גמיש וחשבו אם אתם מעדיפים צמיד צמוד או רפוי יותר. הסוגר והעיצוב משפיעים על הנוחות. בדקו את האורכים הזמינים בעמוד המוצר; נשמח לסייע בבקשת אורך מותאם כאשר התכשיט מאפשר זאת."},"kind":"education","status":"published","legal_reviewed":false}'::jsonb);
